import time
import smbus2
from adafruit_ads1x15 import ADS1115

# I2C configuration for the ADS1115 ADC
I2C_BUS_NUMBER = 1
GAIN = 1
READ_INTERVAL_SECONDS = 0.5

def initialize_i2c_bus(bus_number):
    """Initialize the I2C bus."""
    try:
        return smbus2.SMBus(bus_number)
    except Exception as bus_error:
        print(f"I2C bus error: {bus_error}")
        return None

def create_ads1115(i2c_bus):
    """Create an ADS1115 ADC object."""
    try:
        return ADS1115(i2c_bus)
    except Exception as adc_error:
        print(f"ADS1115 error: {adc_error}")
        return None

def read_adc_channels(adc_device, gain_value, num_channels=4):
    """Read all configured ADC channels."""
    try:
        return [adc_device.read_adc(channel, gain=gain_value) for channel in range(num_channels)]
    except Exception as read_error:
        print(f"ADC read error: {read_error}")
        return None

def format_adc_output(channel_values):
    """Format ADC readings into a table row string."""
    return '| {0:>6} | {1:>6} | {2:>6} | {3:>6} |'.format(*channel_values)

def print_header():
    """Print the header for the ADC output table."""
    print('Reading ADS1115 values, press Ctrl-C to quit...')
    print('-' * 37)

def main():
    """Main function to continuously read and print ADC values."""
    i2c_bus = initialize_i2c_bus(I2C_BUS_NUMBER)
    if i2c_bus is None:
        return

    adc_device = create_ads1115(i2c_bus)
    if adc_device is None:
        return

    print_header()

    try:
        while True:
            channel_values = read_adc_channels(adc_device, gain_value=GAIN)
            if channel_values:
                print(format_adc_output(channel_values))
            time.sleep(READ_INTERVAL_SECONDS)
    except KeyboardInterrupt:
        print("\nExiting program.")
    except Exception as e:
        print(f"Unexpected error: {e}")
    finally:
        # No specific cleanup needed for smbus2 or ADS1115 in this example
        print("Program finished.")

if __name__ == "__main__":
    main()

