import serial
import time
from functools import partial

# Constants for serial port and baud rate
SERIAL_PORT = '/dev/serial0'
BAUD_RATE = 9600


def create_serial_connection(port, baud):
    """Establishes a serial connection."""
    try:
        return serial.Serial(port, baud, timeout=1)
    except serial.SerialException as e:
        print(f"Error opening serial port: {e}")
        return None


def read_gps_data(serial_connection):
    """Reads and returns GPS data from the serial port."""
    try:
        if serial_connection and serial_connection.in_waiting > 0:
            return serial_connection.readline().decode('ascii', errors='replace').strip()
        return None
    except serial.SerialException as e:
        print(f"Error reading from serial port: {e}")
        return None


def parse_coordinates(raw_data):
    """Parses GPS coordinates from raw data."""
    if not raw_data:
        return None, None

    try:
        latitude, longitude = raw_data.split(',')
        latitude = latitude.strip()
        longitude = longitude.strip()

        if not (latitude and longitude):
            return None, None

        latitude_degrees = int(latitude[:2])
        latitude_minutes = int(latitude[2:])
        latitude_direction = latitude[-2:]
        longitude_degrees = int(longitude[:3])
        longitude_minutes = int(longitude[3:])
        longitude_direction = longitude[-2:]

        return latitude_degrees, latitude_minutes, latitude_direction, longitude_degrees, longitude_minutes, longitude_direction
    except (ValueError, IndexError) as e:
        print(f"Error parsing coordinates: {e}")
        return None, None


def format_exif_metadata(latitude_degrees, latitude_minutes, latitude_direction, longitude_degrees, longitude_minutes, longitude_direction):
    """Formats GPS metadata for EXIF."""
    if not all([latitude_degrees, latitude_minutes, latitude_direction, longitude_degrees, longitude_minutes, longitude_direction]):
        return None

    lat_north_south = "N" if latitude_direction == "N" else "S"
    lon_east_west = "E" if longitude_direction == "E" else "W"

    return (f"GPSLatitude={latitude_degrees},{latitude_minutes},{lat_north_south}"
            f"GPSLatitudeRef={latitude_direction} GPSLongitude={longitude_degrees},{longitude_minutes},{longitude_direction}"
            f"GPSLongitudeRef={longitude_direction}")


def degrees_decimal_to_dms(degrees_decimal):
    """Converts decimal degrees to DMS."""
    if not isinstance(degrees_decimal, (int, float)):
        raise TypeError("Input must be a number")

    try:
        sign = "-" if degrees_decimal < 0 else ""
        degrees = int(abs(degrees_decimal))
        decimal_minutes = (abs(degrees_decimal) - degrees) * 60
        minutes = int(decimal_minutes)
        seconds = (decimal_minutes - minutes) * 60
        return sign + f"{degrees}:{minutes}:{seconds:.6f}"
    except (ValueError, TypeError) as e:
        raise ValueError(f"Error converting to DMS: {e}") from e


def number_to_exif_rational(number):
    """Converts a number to a numerator/denominator pair."""
    if not isinstance(number, (int, float)):
        raise TypeError("Input must be a number")
    try:
        denominator = int(1000)
        numerator = int(number * denominator)
        return numerator, denominator
    except (ValueError, TypeError) as e:
        raise ValueError(f"Error converting to rational: {e}") from e


def process_gps_data():
    """Main function to process GPS data."""
    serial_connection = create_serial_connection(SERIAL_PORT, BAUD_RATE)
    if not serial_connection:
        return

    read_from_serial = partial(read_gps_data, serial_connection)

    while True:
        gps_data = read_from_serial()
        if not gps_data:
            continue

        latitude_degrees, latitude_minutes, latitude_direction, longitude_degrees, longitude_minutes, longitude_direction = parse_coordinates(gps_data)
        exif_string = format_exif_metadata(latitude_degrees, latitude_minutes, latitude_direction, longitude_degrees, longitude_minutes, longitude_direction)

        if exif_string:
            print(exif_string)

        # Example usage of DMS conversion:
        dms_latitude = degrees_decimal_to_dms(float(latitude_degrees))
        dms_longitude = degrees_decimal_to_dms(float(longitude_degrees))
        print(f"DMS Latitude: {dms_latitude}")
        print(f"DMS Longitude: {dms_longitude}")

        # Example usage of number to rational conversion:
        rational_latitude = number_to_exif_rational(float(latitude_degrees))
        rational_longitude = number_to_exif_rational(float(longitude_degrees))
        print(f"Rational Latitude: {rational_latitude}")
        print(f"Rational Longitude: {rational_longitude}")


if __name__ == "__main__":
    process_gps_data()

