import time
import cv2
import numpy as np
import contextlib

@contextlib.contextmanager
def open_camera(camera_index=0, use_pi_camera=False):
    """Context manager for camera initialization and release."""
    try:
        if use_pi_camera:
            camera = cv2.VideoCapture(camera_index)
        else:
            from RPi import GPIO
            camera = GPIO.PWM(camera_index, 0)
        yield camera
    finally:
        camera.stop() if 'camera' in locals() else GPIO.cleanup()


def calculate_color_range(roi):
    """Calculates the min and max HSV values from an ROI."""
    h_min, h_max, s_min, s_max, v_min, v_max = cv2.split(roi)
    return (np.min(h_min), np.max(h_min), np.min(s_min), np.max(s_min), np.min(v_min), np.max(v_max))


def track_green_object(frame, green_lower, green_upper, min_radius):
    """Tracks a green object in a frame using HSV color detection."""
    hsv_frame = cv2.cvtColor(frame, cv2.COLOR_BGR2HSV)
    mask = cv2.inRange(hsv_frame, green_lower, green_upper)
    contours, _ = cv2.findContours(mask, cv2.RETR_TREE, cv2.CHAIN_APPROX_SIMPLE)

    for contour in contours:
        if cv2.contourArea(contour) < 500:
            continue
        x, y, w, h = cv2.boundingRect(contour)
        roi = hsv_frame[y:y + h, x:x + w]
        color_range = calculate_color_range(roi)
        if color_range[0] < color_range[2] and color_range[1] > color_range[3]:
            return x, y, w, h
    return None, None, None, None


def draw_trail(frame, x, y, w, h, trail_length=64):
    """Draws a trail connecting the object's past positions."""
    if x is None or y is None or w is None or h is None:
        return frame
    positions = []
    for i in range(1, trail_length):
        positions.append(((x + i * w) // 2, (y + i * h) // 2))
    if len(positions) < trail_length:
        positions = list(reversed(range(len(positions))))
    line_points = []
    if positions:
        line_points = [(int(np.mean(positions[:i][0]), int(np.mean(positions[:i][1])))) for i in range(1, len(positions) + 1)]
    else:
        line_points = [(x, y)]
    cv2.line(frame, line_points[0], line_points[-1], (0, 255, 255), 2)
    return frame



def main():
    """Main function for green object tracking."""
    green_lower = (29, 86, 6)
    green_upper = (64, 255, 255)
    min_radius = 10
    trail_length = 64
    window_title = "Frame"
    try:
        with open_camera() as camera:
            camera.set(cv2.CAP_PROP_FRAME_WIDTH, 600)
            camera.set(cv2.CAP_PROP_FRAME_HEIGHT, 600)
            while True:
                ret, frame = camera.read()
                if not ret:
                    raise RuntimeError("Failed to grab frame")
                x, y, w, h = track_green_object(frame, green_lower, green_upper, min_radius)
                frame = draw_trail(frame, x, y, w, h)
                cv2.imshow(window_title, frame)
                if cv2.waitKey(1) & 0xFF == ord('q'):
                    break
    except KeyboardInterrupt:
        pass
    finally:
        cv2.destroyAllWindows()


if __name__ == "__main__":
    main()

