import time
import cv2
import numpy as np

# Capture frame rate for the security camera
FRAME_RATE = 15

# Warm-up delay after camera initialization
WARM_UP_DELAY = 2

# Motion detection threshold
THRESHOLD = 10

# Camera resolution (width, height)
RESOLUTION = (64, 48)


def initialize_camera():
    """Initializes the camera and returns the capture object."""
    try:
        camera = cv2.VideoCapture(0)
        if not camera.isOpened():
            raise IOError("Cannot open webcam")
        return camera
    except IOError as e:
        print(f"Camera initialization error: {e}")
        return None


def capture_frame(camera):
    """Captures a single frame from the camera."""
    ret, frame = camera.read()
    if not ret:
        raise IOError("Cannot read frame")
    return frame


def calculate_average_pixel_value(frame):
    """Calculates the average pixel value of a frame."""
    return float(np.mean(frame))


def detect_motion(current_average, previous_average, threshold):
    """Detects motion based on the difference between averages."""
    return abs(current_average - previous_average) > threshold


def save_motion_image(frame, filename="motion.jpg"):
    """Saves the current frame as a JPEG image."""
    cv2.imwrite(filename, frame)


def update_baseline(previous_average, current_average):
    """Updates the baseline average pixel value."""
    return current_average


def main():
    """Main function to run the motion detection security camera."""
    camera = initialize_camera()
    if camera is None:
        return

    try:
        # Warm-up period
        print("Warming up...")
        time.sleep(WARM_UP_DELAY)

        previous_average = calculate_average_pixel_value(
            cv2.cvtColor(capture_frame(camera), cv2.COLOR_BGR2GRAY)
        )

        while True:
            current_average = calculate_average_pixel_value(
                cv2.cvtColor(capture_frame(camera), cv2.COLOR_BGR2GRAY)
            )

            if detect_motion(current_average, previous_average, THRESHOLD):
                print("Motion detected!")
                save_motion_image(
                    cv2.cvtColor(capture_frame(camera), cv2.COLOR_BGR2GRAY)
                )
                previous_average = current_average
                print("Updating baseline...")

            time.sleep(2)  # Delay before next check

    except IOError as e:
        print(f"IOError: {e}")
    except KeyboardInterrupt:
        print("Exiting...")
    finally:
        if camera is not None:
            camera.release()


if __name__ == "__main__":
    main()

