import cv2
import os
from typing import Tuple, List, Optional

# Constants
IMAGE_DIR = "images"
MAX_PICTURES = 5
NAME_INPUT = "What is your name? "
CAMERA_INDEX = 0
HAAR_CASCADE_PATH = cv2.data.haarcascades + "haarcascade_frontalface_default.xml"
TIMEOUT_SECS = 1


def create_image_directory(directory_name: str) -> None:
    """Creates a directory if it doesn't exist."""
    try:
        os.makedirs(directory_name, exist_ok=True)
        print(f"Directory '{directory_name}' created or already exists.")
    except OSError as e:
        print(f"Error creating directory '{directory_name}': {e}")
        raise


def get_user_name() -> str:
    """Prompts the user for their name and handles potential errors."""
    while True:
        try:
            name = input(NAME_INPUT)
            if not name:
                print("Name cannot be empty. Please try again.")
            else:
                return name
        except KeyboardInterrupt:
            print("\nExiting program.")
            raise KeyboardInterrupt
        except Exception as e:
            print(f"An unexpected error occurred: {e}")


def initialize_camera(camera_index: int) -> Optional[cv2.VideoCapture]:
    """Initializes the camera with retry logic and error handling."""
    for attempt in range(3):
        try:
            cap = cv2.VideoCapture(camera_index)
            if not cap.isOpened():
                raise RuntimeError(f"Could not open camera at index {camera_index}")
            return cap
        except Exception as e:
            print(f"Camera initialization attempt {attempt + 1} failed: {e}")
            if attempt < 2:
                time.sleep(1)  # Wait before retrying
    raise RuntimeError("Failed to initialize camera after multiple attempts.")


def detect_faces(image, face_cascade) -> Optional[List[Tuple[int, int, int, int]]]:
    """Detects faces in a given image using the Haar cascade classifier."""
    gray = cv2.cvtColor(image, cv2.COLOR_BGR2GRAY)
    faces = face_cascade.detectMultiScale(gray, 1.3, 5)
    return faces if faces is not None else None


def draw_face_boxes(image, faces) -> None:
    """Draws bounding boxes around detected faces on the image."""
    for (x, y, w, h) in faces:
        cv2.rectangle(image, (x, y), (x + w, y + h), (255, 0, 0), 2)


def crop_and_save_face(image, face_count, output_dir) -> None:
    """Crops and saves the detected face to the output directory."""
    face_cascade = cv2.CascadeClassifier(HAAR_CASCADE_PATH)
    if face_cascade.empty():
        raise IOError("Unable to load face cascade classifier.")

    faces = detect_faces(image, face_cascade)
    if faces is None:
        print("No faces detected.")
        return

    faces.sort(key=lambda face: face[0])  # Sort faces by x-coordinate

    if not faces:
        return

    if len(faces) > 1:
        print("Too many faces detected. Saving only the first one.")
        del faces[-1]  # Remove the last face detected

    (x, y, w, h) = faces[0]
    cropped_face = image[y:y + h, x:x + w]
    filename = os.path.join(output_dir, f"{name}.jpg")
    cv2.imwrite(filename, cropped_face)
    print(f"Saved face image: {filename}")


def main() -> None:
    """Main function to capture and save face images."""

    create_image_directory(IMAGE_DIR)

    try:
        cap = initialize_camera(CAMERA_INDEX)
        name = get_user_name()
        print("We will be taking 5 pictures!")

        count = 0
        while count < MAX_PICTURES:
            print(f"Taking picture {count + 1}")
            ret, frame = cap.read()
            if not ret:
                print("Failed to grab frame")
                break

            faces = detect_faces(frame, cv2.CascadeClassifier(HAAR_CASCADE_PATH))
            draw_face_boxes(frame, faces)
            crop_and_save_face(frame, count, IMAGE_DIR)

            count += 1
            if count < MAX_PICTURES:
                print("Press any key to take another picture...")
                cv2.imshow("Faces", frame)
                if cv2.waitKey(1) & 0xFF in (ord('y'), ord('Y')):
                    continue
                else:
                    break

        print("Finished taking pictures.")

    except KeyboardInterrupt:
        print("\nProgram interrupted.")
    except Exception as e:
        print(f"An error occurred: {e}")
    finally:
        if 'cap' in locals() and cap is not None:
            cap.release()
        cv2.destroyAllWindows()


if __name__ == "__main__":
    main()

