# inventory_monitor.py
# Monitors inventory using a QR code scanner on a Raspberry Pi.
# Uses a USB camera and QR code decoding.

import time
import datetime
import os
import sys
from picamera2 import Picamera2
from PIL import Image
from pyzbar import pyzbar

# Configuration
CAMERA_INDEX = 0
LOG_FILE = "inventory_log.csv"
ERROR_LOG = "error_log.txt"
CAPTURE_INTERVAL = 0.2  # seconds

def initialise_camera(camera_index):
    """Initialises the USB camera."""
    try:
        camera = Picamera2()
        camera.configure(camera.create_preview_configuration(main={"format": 'XRGB8888', "size": (640, 480)}))
        camera.start()
        return camera
    except Exception as e:
        log_error(f"Camera initialization failed: {e}")
        return None

def capture_image(camera):
    """Captures an image from the camera."""
    try:
        image = camera.capture_image()
        return image
    except Exception as e:
        log_error(f"Image capture failed: {e}")
        return None

def decode_qr_code(image):
    """Decodes QR codes from an image."""
    try:
        decoded_objects = pyzbar.decode(image)
        if decoded_objects:
            return decoded_objects[0].data.decode("utf-8")
        return None
    except Exception as e:
        log_error(f"QR code decoding failed: {e}")
        return None

def validate_data(data):
    """Validates the decoded data."""
    if data and data.isalnum():
        return True
    return False

def log_data(log_file, item_id, timestamp):
    """Logs the item ID and timestamp to a CSV file."""
    try:
        with open(log_file, "a") as f:
            f.write(f"{timestamp},{item_id}\n")
    except Exception as e:
        log_error(f"Data logging failed: {e}")

def log_error(error_message):
    """Logs an error message to the error log file."""
    timestamp = datetime.datetime.now().isoformat()
    try:
        with open(ERROR_LOG, "a") as f:
            f.write(f"{timestamp}: {error_message}\n")
    except Exception as e:
        print(f"FATAL: Could not write to error log: {e}")

def main():
    """Main function to run the QR code scanner."""
    camera = initialise_camera(CAMERA_INDEX)
    if not camera:
        print("Camera initialization failed. Exiting.")
        sys.exit(1)

    try:
        while True:
            image = capture_image(camera)
            if image:
                qr_data = decode_qr_code(image)
                if qr_data:
                    if validate_data(qr_data):
                        timestamp = datetime.datetime.now().isoformat()
                        log_data(LOG_FILE, qr_data, timestamp)
                        print(f"Item ID: {qr_data}, Timestamp: {timestamp}")
                    else:
                        print(f"Invalid data received: {qr_data}")
                else:
                    print("No QR code found.")
            else:
                print("Failed to capture image.")
            time.sleep(CAPTURE_INTERVAL)

    except KeyboardInterrupt:
        print("Exiting program.")
    finally:
        if camera:
            camera.stop()
            camera.close()
        print("Camera resources released.")

if __name__ == "__main__":
    main()

