# temperature sensor reader on Raspberry Pi over RS485
# Uses a USB to RS485 adapter to talk to a temperature sensor
# Reads temperature data from the sensor and prints it to the console
# Designed for a kids coding lesson on the Raspberry Pi

import serial
import time

# Serial port configuration for the RS485 adapter
SERIAL_PORT = "/dev/ttyUSB0"
BAUD_RATE = 115200
BITS = serial.EIGHTBITS
PARITY = serial.PARITY_NONE
STOP_BITS = serial.STOPBITS_ONE
TIMEOUT = 1

def configure_port(port, baudrate, bits, parity, stopbits, timeout):
    """Configure the serial port settings."""
    try:
        ser = serial.Serial(port, baudrate=baudrate, bytesize=bits, parity=parity, stopbits=stopbits, timeout=timeout)
        return ser
    except serial.SerialException as e:
        print(f"Error configuring serial port: {e}")
        return None

def read_temperature(serial_port):
    """Read temperature data from the serial port."""
    try:
        line = serial_port.readline().decode('ascii', errors='replace').strip()
        if line:
            return float(line)
        return None
    except ValueError:
        print("Error: Could not convert data to float.")
        return None
    except Exception as e:
        print(f"Error reading from serial port: {e}")
        return None

def display_temperature(temperature):
    """Display the temperature in a user-friendly format."""
    if temperature is not None:
        print(f"Temperature: {temperature:.1f} C")

def main():
    """Main function to continuously read and display temperature."""
    serial_connection = configure_port(SERIAL_PORT, BAUD_RATE, BITS, PARITY, STOP_BITS, TIMEOUT)
    if serial_connection is None:
        return

    try:
        while True:
            temperature_value = read_temperature(serial_connection)
            display_temperature(temperature_value)
            time.sleep(0.5)
    except KeyboardInterrupt:
        print("Program stopped by user.")
    finally:
        if serial_connection and serial_connection.is_open:
            serial_connection.close()
            print("Serial port closed.")

if __name__ == "__main__":
    main()

