# altitude monitor for a Raspberry Pi using a BMP280 over I2C
# Subcategory tag: altitude monitor
import time
import logging
from typing import List, Tuple

try:
    from smbus2 import SMBus
except ImportError:
    from smbus import SMBus
from bmp280 import BMP280


# Configure logging for the altitude monitor
logging.basicConfig(level=logging.INFO, format="%(asctime)s %(message)s")


def read_raw_samples(bus: SMBus, device_address: int, sample_count: int) -> List[int]:
    """Read raw pressure samples from the BMP280 sensor."""
    raw_samples = []
    for _ in range(sample_count):
        try:
            raw_pressure = bus.read_word_data(device_address, 0xF7)
            raw_samples.append(raw_pressure)
        except OSError as bus_error:
            logging.warning("BMP280 read error: %s", bus_error)
            # Keep going even if there's an error; retry later
        time.sleep(0.05)
    return raw_samples


def calculate_truncated_mean(raw_samples: List[int]) -> int:
    """Return the median of the raw pressure samples."""
    # Sort the samples and pick the middle one
    sorted_samples = sorted(raw_samples)
    middle_index = len(sorted_samples) // 2
    return sorted_samples[middle_index]


def initialize_bmp280(bus: SMBus, device_address: int) -> BMP280:
    """Initialize the BMP280 sensor and return it."""
    try:
        bmp280 = BMP280(i2c_dev=bus, address=device_address)
        return bmp280
    except OSError as init_error:
        raise RuntimeError("BMP280 initialization failed: %s" % init_error) from init_error


def collect_baseline(bmp280: BMP280, sample_count: int) -> int:
    """Collect a number of samples and return the median."""
    raw_samples = read_raw_samples(bmp280.i2c_dev, bmp280.address(), sample_count)
    return calculate_truncated_mean(raw_samples)


def read_altitude(bmp280: BMP280) -> float:
    """Read the current altitude from the BMP280 sensor."""
    try:
        return bmp280.get_altitude()
    except OSError as read_error:
        raise RuntimeError("BMP280 altitude read failed: %s" % read_error) from read_error


def main() -> None:
    """Main entry point for the altitude monitor."""
    device_address = 0x76
    i2c_bus_number = 1
    sample_count = 100
    baseline_window = 75

    try:
        # Open the I2C bus
        i2c_bus = SMBus(i2c_bus_number)
    except OSError as bus_error:
        logging.error("Could not open I2C bus %d: %s", i2c_bus_number, bus_error)
        return

    try:
        # Initialize the BMP280 sensor
        bmp280 = initialize_bmp280(i2c_bus, device_address)
        logging.info("BMP280 initialized at address 0x%02X", device_address)

        # Collect a baseline pressure reading
        baseline_pressure = collect_baseline(bmp280, sample_count)
        logging.info("Collected baseline pressure: %d hPa", baseline_pressure)

        # Allow the sensor to settle before the first reading
        time.sleep(2)

        # Continuously report altitude
        while True:
            try:
                current_altitude = read_altitude(bmp280)
                logging.info("Current altitude: %.2f metres", current_altitude)
                time.sleep(1)
            except RuntimeError as read_error:
                logging.error("BMP280 read failed: %s", read_error)
                time.sleep(1)

    except RuntimeError as init_error:
        logging.error("Initialization failed: %s", init_error)
    except Exception as e:
        logging.exception("Unexpected error: %s", e)
    finally:
        # Close the I2C bus
        try:
            i2c_bus.close()
        except AttributeError:
            # SMBus doesn't have close() if it wasn't opened
            pass
        logging.info("Altitude monitor stopped.")


if __name__ == "__main__":
    main()

