# Logs temperature data from a UART sensor to a CSV file on a Raspberry Pi
# Designed for a kids coding lesson

import serial
import time
import csv
import os

# --- Configuration ---
SERIAL_PORT = '/dev/ttyACM0'  # UART port for the sensor
BAUD_RATE = 115200           # Baud rate for serial communication
TIMEOUT = 1                  # Timeout for reading from the serial port
CSV_FILE = 'temperature_log.csv'  # Name of the CSV file to store data

# --- Functions ---
def configure_serial(port, baudrate, timeout):
    """Configures and returns a serial port object."""
    try:
        ser = serial.Serial(port, baudrate, timeout=timeout)
        return ser
    except serial.SerialException as e:
        print(f"Error opening serial port: {e}")
        return None

def read_temperature(serial_port):
    """Reads temperature data from the serial port."""
    try:
        line = serial_port.readline().decode('ascii', errors='replace').strip()
        if line:
            return float(line)
        return None
    except ValueError:
        print("Invalid temperature data received.")
        return None
    except Exception as e:
        print(f"Error reading from serial port: {e}")
        return None

def convert_to_fahrenheit(celsius):
    """Converts Celsius to Fahrenheit."""
    return (celsius * 9/5) + 32

def log_data(csv_file, timestamp, celsius, fahrenheit):
    """Logs the data to the CSV file."""
    try:
        with open(csv_file, 'a', newline='') as file:
            writer = csv.writer(file)
            writer.writerow([timestamp, celsius, fahrenheit])
    except IOError as e:
        print(f"Error writing to CSV file: {e}")

def create_header(csv_file):
    """Creates the header row in the CSV file if it doesn't exist."""
    if not os.path.exists(csv_file):
        with open(csv_file, 'w', newline='') as file:
            writer = csv.writer(file)
            writer.writerow(['Timestamp', 'Celsius', 'Fahrenheit'])

def main():
    """Main function to read temperature and log data."""
    serial_connection = configure_serial(SERIAL_PORT, BAUD_RATE, TIMEOUT)

    if serial_connection is None:
        print("Failed to configure serial port. Exiting.")
        return

    try:
        while True:
            temperature_celsius = read_temperature(serial_connection)
            if temperature_celsius is not None:
                temperature_fahrenheit = convert_to_fahrenheit(temperature_celsius)
                timestamp = time.strftime('%Y-%m-%d %H:%M:%S')
                log_data(CSV_FILE, timestamp, temperature_celsius, temperature_fahrenheit)
                print(f"Logged: {timestamp}, {temperature_celsius:.2f}C, {temperature_fahrenheit:.2f}F")
            time.sleep(1)  # Wait for 1 second

    except KeyboardInterrupt:
        print("Program terminated by user.")
    finally:
        if serial_connection:
            serial_connection.close()
            print("Serial port closed.")

if __name__ == "__main__":
    main()

