# altitude monitor for a Raspberry Pi using a BMP280 over I2C
# Subcategory tag: altitude monitor
import time
import board
import busio
import adafruit_bmp280

# I2C bus and device configuration for the BMP280
I2C_BUS_NUMBER = 1
I2C_SDA_PIN = board.SCL
I2C_SCL_PIN = board.SDA


def read_baseline_pressure(i2c_bus, sensor_device):
    """Read a baseline pressure from the BMP280 over I2C."""
    # Collect several pressure samples to average out sensor noise
    pressure_samples = []
    for _ in range(10):
        try:
            pressure_samples.append(sensor_device.pressure)
            time.sleep(1)
        except OSError:
            print("BMP280 read failed, retrying")
            continue
    # Average the collected samples to produce a stable baseline
    if not pressure_samples:
        return 0.0
    return sum(pressure_samples) / len(pressure_samples)


def read_altitude(i2c_bus, sensor_device, baseline_pressure):
    """Read the relative altitude from the BMP280 compared to baseline."""
    # Read a fresh pressure sample and compute altitude relative to baseline
    try:
        current_pressure = sensor_device.pressure
        altitude_value = 44330 * (1.0 - (current_pressure / baseline_pressure)**(1/5.255))
        return round(altitude_value, 2)
    except OSError:
        return None


def main():
    # Set up the I2C bus and the BMP280 sensor
    i2c_bus = busio.I2C(I2C_SDA_PIN, I2C_SCL_PIN)
    bmp280_sensor = adafruit_bmp280.Adafruit_BMP280_I2C(i2c_bus)
    baseline_pressure = 0.0
    try:
        # Establish a baseline pressure after the sensor warms up
        baseline_pressure = read_baseline_pressure(i2c_bus, bmp280_sensor)
        while baseline_pressure == 0.0:
            baseline_pressure = read_baseline_pressure(i2c_bus, bmp280_sensor)
            time.sleep(1)
        # Continuously report relative altitude from the baseline
        while True:
            altitude_value = read_altitude(i2c_bus, bmp280_sensor, baseline_pressure)
            if altitude_value is not None:
                print("Relative altitude: {0} meters".format(altitude_value))
            time.sleep(1)
    except KeyboardInterrupt:
        print("Stopping altitude monitor")
    except Exception as error:
        print("An error occurred: {0}".format(error))


if __name__ == "__main__":
    main()

