#!/usr/bin/env python3
"""
Continuously read power and battery status from a Raspberry Pi UPS Plus over I2C.
Logs supply and battery power levels and charging state.
"""

import time
import smbus2
import logging
from ina219 import INA219, DeviceRangeError

# Logging configuration for the UPS Plus power monitor
logging.basicConfig(level=logging.INFO, format="%(asctime)s %(message)s")
logger = logging.getLogger("ups")


def open_i2c_bus(i2c_bus_number=1):
    """Open and return the I2C bus for the UPS Plus."""
    try:
        return smbus2.SMBus(i2c_bus_number)
    except Exception as bus_error:
        logger.error("Failed to open I2C bus: %s", bus_error)
        raise


def initialize_ina219(shunt_resistor, bus_number=1):
    """Initialize and return an INA219 sensor object."""
    try:
        ina = INA219(shunt_resistor, busnum=bus_number)
        ina.configure()
        return ina
    except Exception as init_error:
        logger.error("Failed to initialize INA219: %s", init_error)
        raise


def read_power_levels(i2c_bus, supply_ina, battery_ina):
    """Read and return supply and battery power levels."""
    try:
        supply_voltage = ina.get_voltage()
        supply_current = ina.get_current()
        supply_power = supply_voltage * supply_current
        battery_voltage = battery_ina.get_voltage()
        battery_current = battery_ina.get_current()
        battery_power = battery_voltage * battery_current
        return supply_voltage, supply_current, supply_power, battery_voltage, battery_current, battery_power
    except DeviceRangeError:
        logger.warning("Sensor reading out of range")
        return None, None, None, None, None, None
    except Exception as read_error:
        logger.error("Failed to read power levels: %s", read_error)
        return None, None, None, None, None, None


def describe_state(supply_voltage, supply_current, supply_power, battery_voltage, battery_current, battery_power):
    """Return a human readable power status string."""
    if supply_voltage is None or supply_current is None or supply_power is None:
        return "unknown"
    if battery_voltage is None or battery_current is None or battery_power is None:
        return "unknown"
    if battery_current > 0:
        return "Charging"
    if battery_current < 0:
        return "Discharging"
    return "Full"


def run_ups_monitor():
    """Continuously monitor and print UPS Plus power state."""
    try:
        i2c_bus = open_i2c_bus()
        supply_ina = initialize_ina219(0.00725, bus_number=i2c_bus.number)
        battery_ina = initialize_ina219(0.005, bus_number=i2c_bus.number)
        while True:
            supply_voltage, supply_current, supply_power, battery_voltage, battery_current, battery_power = read_power_levels(i2c_bus, supply_ina, battery_ina)
            if all(value is not None for value in [supply_voltage, supply_current, supply_power, battery_voltage, battery_current, battery_power]):
                state = describe_state(supply_voltage, supply_current, supply_power, battery_voltage, battery_current, battery_power)
                logger.info("Supply: %.3f V %.3f mA %.3f mW | Battery: %.3f V %.3f mA %.3f mW | State: %s",
                             supply_voltage, supply_current, supply_power, battery_voltage, battery_current, battery_power, state)
            time.sleep(2)
    except KeyboardInterrupt:
        logger.info("Stopping UPS Plus monitor")
    except Exception as main_error:
        logger.error("Fatal UPS Plus error: %s", main_error)
    finally:
        # Release the I2C bus on shutdown
        try:
            i2c_bus.close()
        except Exception:
            pass


if __name__ == "__main__":
    run_ups_monitor()

