# -*- coding: utf-8 -*-
"""
Read temperature and humidity from a DHT11 sensor and send data to an API.
"""

import time
import requests
from requests import Response
from gpiozero import DHT11
from gpiozero.exc import GPIODeviceError

# Configuration
DHT_PIN = 4  # GPIO pin connected to the DHT11 data pin
API_ENDPOINT = "http://127.0.0.1:5000/data"
READ_INTERVAL = 5  # Seconds between sensor readings


def read_dht11_sensor(pin):
    """Read temperature and humidity from the DHT11 sensor."""
    try:
        sensor = DHT11(pin)
        sensor.wait_for_reading()
        temperature = sensor.temperature
        humidity = sensor.humidity
        return temperature, humidity
    except GPIODeviceError as e:
        print(f"Error reading DHT11 sensor: {e}")
        return None, None
    except Exception as e:
        print(f"Unexpected error reading sensor: {e}")
        return None, None


def send_data_to_api(temperature, humidity, api_url):
    """Send temperature and humidity data to the API."""
    payload = {"temperature": temperature, "humidity": humidity}
    try:
        response = requests.post(api_url, json=payload)
        response.raise_for_status()  # Raise HTTPError for bad responses (4xx or 5xx)
        print(f"Data sent successfully. Status code: {response.status_code}")
    except requests.exceptions.RequestException as e:
        print(f"Error sending data to API: {e}")


def main():
    """Main function to read sensor and send data."""
    try:
        while True:
            temperature, humidity = read_dht11_sensor(DHT_PIN)

            if temperature is not None and humidity is not None:
                send_data_to_api(temperature, humidity, API_ENDPOINT)

            time.sleep(READ_INTERVAL)

    except KeyboardInterrupt:
        print("Program terminated by user.")
    except Exception as e:
        print(f"An unexpected error occurred: {e}")


if __name__ == "__main__":
    main()

