#!/usr/bin/python3
# -*- coding: utf-8 -*-

"""
Mirrors a mechanical switch to an LED using an MCP23017 I2C GPIO expander.
"""

import time
from MCP23017_I2C import GPIO_CHIP, MCP23017Error

# Constants for GPIO expander pins
SWITCH_PIN = 7
LED_PIN = 0
I2C_BUS = 0
I2C_ADDRESS = 0


def setup_gpio(expander):
    """Configure the switch pin as input with pull-up and the LED pin as output."""
    try:
        expander.setup(SWITCH_PIN, 'IN', pull_up_down=GPIOCHIP.PUD_UP)
        expander.setup(LED_PIN, 'OUT')
        return True
    except MCP23017Error as e:
        print(f"GPIO setup error: {e}")
        return False


def read_switch_state(expander):
    """Read the current state of the switch pin."""
    try:
        return expander.input(SWITCH_PIN)
    except MCP23017Error as e:
        print(f"Switch read error: {e}")
        return None


def mirror_switch_state(expander, led_state):
    """Set the LED state based on the mirrored switch state."""
    try:
        expander.output(LED_PIN, not led_state)
        return True
    except MCP23017Error as e:
        print(f"LED write error: {e}")
        return False


def main():
    """Main function to continuously mirror the switch state to the LED."""
    expander = None
    try:
        expander = GPIO_CHIP(I2C_BUS, I2C_ADDRESS)
        if not setup_gpio(expander):
            return

        led_state = False
        while True:
            switch_state = read_switch_state(expander)
            if switch_state is not None:
                mirrored_state = not switch_state
                if mirrored_state != led_state:
                    if not mirror_switch_state(expander, led_state):
                        break
                    led_state = mirrored_state
                print(f"Led {'ON' if led_state else 'OFF'}")
            time.sleep(0.1)
    except KeyboardInterrupt:
        print("Exiting program.")
    except Exception as e:
        print(f"An unexpected error occurred: {e}")
    finally:
        # Ensure LED is off on exit
        if expander:
            try:
                expander.output(LED_PIN, False)
            except MCP23017Error:
                pass


if __name__ == "__main__":
    main()

