import time
import logging
import RPi.GPIO as GPIO
from dogen import DOG, DOGError

# Configure logging
logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')

# Global variables
running = True
log_file_path = ""

class CommandHandler:
    """
    Handles user commands related to data logging and transmission.
    """
    def __init__(self):
        self.dog = None
        self.log_file = None
        self.log_lock = threading.Lock()

    def start_logging(self, log_file_path):
        """Starts data logging with the specified file path."""
        global running
        running = True
        self.log_file_path = log_file_path
        try:
            self.log_file = open(log_file_path, 'a')
            self.dog = DOG()
            self.dog.start(self.log_file)
            logging.info(f"Data logging started on '{log_file_path}'")
        except DOGError as e:
            logging.error(f"Error initializing DOG: {e}")
            running = False
        except Exception as e:
            logging.error(f"Unexpected error during logging setup: {e}")
            running = False

    def stop_logging(self):
        """Stops data logging."""
        global running
        running = False
        if self.log_file:
            self.log_file.close()
            logging.info("Data logging stopped.")

    def display_log(self):
        """Displays the contents of the log file."""
        try:
            with self.log_lock:
                if self.log_file:
                    try:
                        self.log_file.seek(0)
                        print(self.log_file.read())
                    except IOError as e:
                        logging.error(f"Error reading log file: {e}")
        except Exception as e:
            logging.error(f"Error displaying log: {e}")

    def send_data(self, data):
        """Sends data via DOG."""
        if self.dog:
            try:
                self.dog.send(data)
                logging.info(f"Data sent: {data}")
            except DOGError as e:
                logging.error(f"Error sending data: {e}")

    def write_to_log(self, data):
        """Writes data directly to the log file."""
        if self.log_file:
            try:
                with self.log_lock:
                    self.log_file.write(data + "\n")
                    self.log_file.flush()  # Ensure data is written immediately
                logging.debug(f"Data written to log: {data}")
            except IOError as e:
                logging.error(f"Error writing to log file: {e}")

    def process_command(self, command):
        """
        Processes user commands.

        Args:
            command (str): The command to process.
        """
        if not running:
            print("Logging is not active.")
            return

        try:
            if command.startswith("start"):
                if not self.log_file:
                    self.start_logging(self.log_file_path)
                else:
                    print("Logging is already active.")
            elif command.startswith("stop"):
                self.stop_logging()
            elif command.startswith("display"):
                self.display_log()
            elif command.startswith("send"):
                parts = command.split()
                if len(parts) > 1:
                    self.send_data(" ".join(parts[1:]))
                else:
                    print("Usage: send <data>")
            elif command.startswith("write"):
                parts = command.split()
                if len(parts) > 1:
                    self.write_to_log(" ".join(parts[1:]))
                else:
                    print("Usage: write <data>")
            elif command.startswith("help"):
                print("Available commands:")
                print("  start <log_file_path> - Start logging to the specified file.")
                print("  stop - Stop logging.")
                print("  display - Display the current contents of the log file.")
                print("  send <data> - Send data via DOG.")
                print("  write <data> - Write data directly to the log file.")
                print("  help - Display this help message.")
                print("  exit - Exit the program.")
            elif command.startswith("exit"):
                self.stop_logging()
                print("Exiting program.")
                sys.exit(0)
            else:
                print("Invalid command.")
        except Exception as e:
            logging.error(f"Error processing command: {e}")
            print(f"An error occurred: {e}")


def main():
    """
    Main function to handle user commands and data logging.
    """
    global running
    command_handler = CommandHandler()

    # Set GPIO numbering mode (if needed for other functionalities later)
    GPIO.setmode(GPIO.BCM) 

    try:
        while True:
            command = input("JAYES@ROVER53:\t")
            command_handler.process_command(command)

    except KeyboardInterrupt:
        print("\nKeyboard interrupt detected. Exiting...")
    finally:
        command_handler.stop_logging()  # Ensure logging is stopped on exit
        GPIO.cleanup()  # Clean up GPIO resources
        logging.info("Program terminated, GPIO cleaned up.")


if __name__ == "__main__":
    main()

