# Functional approach to updating configuration
def update_config(update: dict) -> dict:
    """Updates the configuration with new values, handling nested updates."""
    global config
    new_config = type(**update)(**update)
    config = type(**config)(**{k: merge(v, new_config[k]) for k, v in DEFAULT_CONFIG.items() if k in new_config and k in DEFAULT_CONFIG})
    return config


# Helper function for merging dictionaries (with type hints)
def merge(v: dict, u: dict) -> dict:
    """Merges two dictionaries, prioritizing values from 'u'."""
    for k, v_val in u.items():
        if k in v:
            v[k] = type(v[k], type(v_val))(**{**v[k], **v_val})  # Merge nested dictionaries recursively
        else:
            v[k] = u[k]
    return v


