import time
import logging
from typing import Union
from serial import Serial, SerialException

# Configure logging for servo motor controller
logging.basicConfig(level=logging.INFO, format="%(asctime)s %(message)s")


class ServoMotorController:
    """Encapsulates Modbus RTU communication with a servo motor controller."""

    def __init__(self, port: str = "/dev/serial0", baudrate: int = 115200):
        """Initializes the controller with the serial port and baud rate."""
        self.port = port
        self.baudrate = baudrate
        self.ser = None
        self.register_map = {
            "CONTROL": {"R/W": "W", "Register": 0, "functioncode": 6},
            "STATUS": {"R/W": "R", "Register": 2, "functioncode": 3},
            "Velocity": {"R/W": "W", "Register": 4, "functioncode": 10},
            "VelocitySetpoint": {"R/W": "W", "Register": 6, "functioncode": 10},
            "Position": {"R/W": "R", "Register": 8, "functioncode": 3},
            "PositionSetpoint": {"R/W": "R", "Register": 10, "functioncode": 3},
        }

    def open(self) -> bool:
        """Opens the serial port and initializes communication."""
        try:
            self.ser = Serial(port=self.port, baudrate=self.baudrate, timeout=1)
            self.ser.set/tty.set_parits(8, 1, 1)
            self.ser.set/tty.set_nrts(1)
            self.ser.set/tty.set_csi(0)
            self.ser.set/tty.set_block(1)
            self.ser.set/tty.set_escape(0)
            self.ser.set/tty.set_bits(0x80)
            self.ser.open()
            logging.info(f"Opened serial port {self.port} at {self.baudrate} baud")
            return True
        except SerialException as e:
            logging.error(f"Could not open serial port: {e}")
            return False

    def close(self) -> None:
        """Closes the serial port."""
        if self.ser:
            self.ser.close()
            logging.info("Closed serial port")

    def _write_register(self, register_name: str, value: Union[int, str]) -> bool:
        """Writes to a specific register."""
        try:
            register = self.register_map[register_name]
            if register["R/W"] != "W":
                raise ValueError(f"Register {register_name} is read-only")
            self.ser.write(f"\n{register['Register']:02X}{" ".join([str(value))] * (register["functioncode"] // 2 - 1)).encode())
            return True
        except KeyError:
            logging.error(f"Invalid register name: {register_name}")
            return False
        except Exception as e:
            logging.error(f"Failed to write to register {register_name}: {e}")
            return False

    def _read_register(self, register_name: str, number_of_bytes: int = 2) -> Union[int, str, bool]:
        """Reads from a specific register."""
        try:
            register = self.register_map[register_name]
            if register["R/W"] != "R":
                raise ValueError(f"Register {register_name} is write-only")
            result = self.ser.read_register(register["Register"], number_of_bytes)
            if result is None:
                return False
            return int(result)
        except KeyError:
            logging.error(f"Invalid register name: {register_name}")
            return False
        except Exception as e:
            logging.error(f"Failed to read from register {register_name}: {e}")
            return False


    def set_control(self, value: Union[int, str]) -> bool:
        """Sets the control register."""
        return self._write_register("CONTROL", value)

    def get_status(self) -> bool:
        """Gets the status register."""
        return self._read_register("STATUS")

    def set_velocity(self, value: Union[int, str]) -> bool:
        """Sets the velocity register."""
        return self._write_register("Velocity", value)

    def set_velocity_setpoint(self, value: Union[int, str]) -> bool:
        """Sets the velocity setpoint register."""
        return self._write_register("VelocitySetpoint", value)

    def get_position(self) -> Union[int, str]:
        """Gets the position register."""
        return self._read_register("Position")

    def set_position_setpoint(self, value: Union[int, str]) -> bool:
        """Sets the position setpoint register."""
        return self._write_register("PositionSetpoint", value)


def main():
    """Main entry point demonstrating servo motor control."""
    controller = ServoMotorController()
    if not controller.open():
        return

    try:
        while True:
            # Control the motor
            controller.set_control(6)
            time.sleep(1)

            # Read the status
            status = controller.get_status()
            logging.info(f"Status: {status}")

            # Read the position
            position = controller.get_position()
            logging.info(f"Position: {position}")

            # Set a velocity
            controller.set_velocity(100)
            time.sleep(1)

            # Read the position again
            position = controller.get_position()
            logging.info(f"Position after velocity: {position}")

            # Set a position setpoint
            controller.set_position_setpoint(2000)
            time.sleep(1)

    except KeyboardInterrupt:
        logging.info("Stopping servo motor controller")
    finally:
        controller.close()


if __name__ == "__main__":
    main()

