import serial
from pymodbus.client import ModbusSerialClient
from pymodbus.constants import Endian
from pymodbus.payload import BinaryPayloadDecoder

# Configure logging for the servo controller
logging.basicConfig(level=logging.INFO, format="%(asctime)s %(message)s")

# Modbus slave address for the servo motor
SERVO_MODBUS_ADDRESS = 1

# Serial port for the Raspberry Pi
SERIAL_PORT = "/dev/serial0"


class ServoMotor:
    """Controls a servo motor via Modbus RTU over the Raspberry Pi UART."""

    def __init__(self, port, baudrate, timeout):
        """Initialize the Modbus connection to the servo motor."""
        self.client = ModbusSerialClient(
            method="rtu", port=port, baudrate=baudrate, parity="N", stopbits=1, bytesize=8
        )
        self.timeout = timeout

    def connect(self):
        """Open the serial port and establish the Modbus connection."""
        return self.client.connect()

    def close(self):
        """Close the Modbus connection."""
        self.client.close()

    def _read_register(self, register_address, data_type="float"):
        """Read a register and decode it as the specified data type."""
        try:
            if data_type == "float":
                result = self.client.read_holding_registers(register_address, 2, unit=SERVO_MODBUS_ADDRESS)
                if result.isError():
                    raise Exception(f"Modbus error: {result}")
                decoder = BinaryPayloadDecoder.fromRegisters(result.registers, byteorder=Endian.Big, wordorder=Endian.Little)
                return decoder.decode_32bit_float()
            elif data_type == "uint16":
                result = self.client.read_holding_registers(register_address, 1, unit=SERVO_MODBUS_ADDRESS)
                if result.isError():
                    raise Exception(f"Modbus error: {result}")
                return result.registers[0]
            else:
                raise ValueError("Invalid data type specified.")
        except Exception as e:
            logging.error(f"Error reading register {register_address}: {e}")
            return None

    def set_angle(self, angle_degrees):
        """Set the servo angle in degrees."""
        try:
            # Convert degrees to a 16-bit two's complement value
            angle_value = int(angle_degrees)
            self._write_register(0, "uint16", angle_value)
            logging.info(f"Servo angle set to {angle_degrees} degrees")
        except Exception as e:
            logging.error(f"Error setting servo angle: {e}")

    def get_feedback(self):
        """Read the servo feedback register."""
        try:
            return self._read_register(0, "uint16")
        except Exception as e:
            logging.error(f"Error reading servo feedback: {e}")
            return None

    def move_to(self, target_angle):
        """Move the servo to a target angle."""
        if self.get_feedback() is None:
            logging.warning("Could not read current servo position. Moving to target angle will fail.")
            return

        if abs(target_angle - self.get_feedback()) > 5:
            self.set_angle(target_angle)
        else:
            logging.info(
                f"Servo already close enough to target angle {target_angle}. Difference is {abs(target_angle - self.get_feedback())}"
            )


def main():
    """Main function to demonstrate servo motor control."""

    try:
        # Create the servo motor controller
        servo_controller = ServoMotor(SERIAL_PORT, 115200, 0.05)

        # Connect to the Modbus slave
        if not servo_controller.connect():
            raise Exception("Failed to connect to Modbus slave.")

        # Move the servo to a target angle
        target_angle = 90
        servo_controller.move_to(target_angle)

        # Read the servo feedback
        feedback_value = servo_controller.get_feedback()
        if feedback_value is not None:
            logging.info(f"Servo feedback: {feedback_value}")

    except serial.SerialException as e:
        logging.error(f"Serial port error: {e}")
    except Exception as e:
        logging.error(f"An unexpected error occurred: {e}")
    finally:
        # Ensure the Modbus connection is closed
        if hasattr(servo_controller, "client"):
            servo_controller.client.close()


if __name__ == "__main__":
    main()

