import smbus2
import time
from datetime import datetime
import logging

# Logging for the DS1338 RTC driver
logging.basicConfig(level=logging.INFO, format="%(asctime)s %(message)s")

# DS1338 register addresses on the I2C bus
REG_SECONDS = 0x00
REG_MINUTES = 0x01
REG_HOURS = 0x02
REG_DAY = 0x03
REG_DATE = 0x04
REG_MONTH = 0x05
REG_YEAR = 0x06
REG_CONTROL = 0x07


class DS1338:
    """Driver for the DS1338 real-time clock (RTC) on I2C."""

    def __init__(self, i2c_bus_number=1, device_address=0x68):
        """Initialize the DS1338 RTC.

        Args:
            i2c_bus_number: The I2C bus number the RTC is connected to.
            device_address: The I2C address of the DS1338 device.
        """
        try:
            self.i2c_bus = smbus2.SMBus(i2c_bus_number)
            self.device_address = device_address
            # Check if the device is present by reading a register
            self._read_register(REG_SECONDS, 0x00)
            logging.info("DS1338 found on I2C bus %d address %02X", i2c_bus_number, device_address)
        except Exception as e:
            logging.error("DS1338 not found on I2C bus %d: %s", i2c_bus_number, e)
            raise

    def _bcd_to_int(self, bcd_value):
        """Convert a BCD value to an integer."""
        try:
            return (bcd_value >> 4) * 10 + (bcd_value & 0x0F)
        except TypeError:
            logging.error("Invalid BCD value: %s", bcd_value)
            return None

    def _int_to_bcd(self, integer_value):
        """Convert an integer to BCD format."""
        if not 0 <= integer_value <= 99:
            raise ValueError("Integer must be between 0 and 99 for BCD conversion.")
        return (integer_value // 10 << 4) | (integer_value % 10)

    def _read_register(self, register_address, read_value=False):
        """Read or write a value to a specific register."""
        try:
            if read_value:
                return self.i2c_bus.read_byte_data(self.device_address, register_address)
            else:
                self.i2c_bus.write_byte_data(self.device_address, register_address, read_value)
        except OSError as e:
            logging.error("I2C write/read error: %s", e)
            raise

    def read_datetime(self, century=21):
        """Read the current time from the RTC and return a datetime object."""
        try:
            seconds = self._bcd_to_int(self._read_register(REG_SECONDS))
            minutes = self._bcd_to_int(self._read_register(REG_MINUTES))
            hours = self._bcd_to_int(self._read_register(REG_HOURS) & 0x3F) # 24-hour mode
            day = self._bcd_to_int(self._read_register(REG_DAY))
            date = self._bcd_to_int(self._read_register(REG_DATE))
            month = self._bcd_to_int(self._read_register(REG_MONTH))
            year = self._bcd_to_int(self._read_register(REG_YEAR))

            year = (century - 1) * 100 + year
            return datetime(year, month, date, hours, minutes, seconds)
        except Exception as e:
            logging.error("Error reading RTC time: %s", e)
            return None

    def write_datetime(self, dt_object):
        """Write the given datetime object to the RTC registers."""
        try:
            self._write_register(REG_SECONDS, self._int_to_bcd(dt_object.second))
            self._write_register(REG_MINUTES, self._int_to_bcd(dt_object.minute))
            self._write_register(REG_HOURS, self._int_to_bcd(dt_object.hour)) # 24-hour format
            self._write_register(REG_DAY, self._int_to_bcd(dt_object.isoweekday()))
            self._write_register(REG_DATE, self._int_to_bcd(dt_object.day))
            self._write_register(REG_MONTH, self._int_to_bcd(dt_object.month))
            self._write_register(REG_YEAR, self._int_to_bcd(dt_object.year % 100))
        except Exception as e:
            logging.error("Error writing RTC time: %s", e)
            raise

    def _write_register(self, register_address, write_value):
        """Write a value to a specific register."""
        self._read_register(register_address, write_value)


def main():
    """Main entry point: read and print the RTC time."""
    try:
        rtc = DS1338(i2c_bus_number=1, device_address=0x68)
        current_time = rtc.read_datetime()
        if current_time:
            print("RTC time: %s", current_time.strftime("%Y-%m-%d %H:%M:%S"))
    except Exception as e:
        logging.error("RTC error: %s", e)


if __name__ == "__main__":
    main()

