import smbus2
from datetime import datetime
import contextlib

# DS1338 RTC I2C address
DS1338_ADDRESS = 0x68

# Register addresses
REG_SECONDS = 0x00
REG_MINUTES = 0x01
REG_HOURS = 0x02
REG_DAY = 0x03
REG_DATE = 0x04
REG_MONTH = 0x05
REG_YEAR = 0x06
REG_CONTROL = 0x07


class DS1338:
    """Driver for the DS1338 RTC on I2C."""

    def __init__(self, i2c_bus=1):
        """Open the I2C bus."""
        try:
            self.bus = smbus2.SMBus(i2c_bus)
        except Exception as e:
            raise IOError(f"Failed to open I2C bus {i2c_bus}: {e}")
        self._closed = False

    def __enter__(self):
        """Context manager entry."""
        return self

    def __exit__(self, exc_type, exc_val, exc_tb):
        """Close the I2C bus on exit."""
        if not self._closed:
            self.close()

    def close(self):
        """Close the I2C bus."""
        self._closed = True
        if self.bus:
            self.bus.close()


    def _bcd_to_int(self, bcd_value):
        """Decode a 2x4bit BCD value to an integer."""
        try:
            return int(f"{bcd_value // 16:01}{bcd_value % 16:01}")
        except ValueError:
            raise ValueError("Invalid BCD value")

    def _int_to_bcd(self, integer_value):
        """Encode an integer to BCD."""
        if not 0 <= integer_value <= 99:
            raise ValueError("Integer must be between 0 and 99")
        tens, units = divmod(integer_value, 10)
        return (tens * 16) + units


    def read_all(self):
        """Read all RTC registers."""
        try:
            data = self.bus.read_i2c_block_data(DS1338_ADDRESS, 0x00, 7)
        except Exception as e:
            raise IOError(f"Failed to read DS1338 registers: {e}")
        return data


    def write_all(self, seconds, minutes, hours, day, date, month, year):
        """Write all RTC registers."""
        data = [self._int_to_bcd(seconds), self._int_to_bcd(minutes), self._int_to_bcd(hours), day,
                self._int_to_bcd(date), self._int_to_bcd(month), self._int_to_bcd(year)]
        try:
            self.bus.write_i2c_block_data(DS1338_ADDRESS, 0x00, data)
        except Exception as e:
            raise IOError(f"Failed to write DS1338 registers: {e}")


    def read_datetime(self, century=21):
        """Decode raw register data into a datetime object."""
        data = self.read_all()
        year = (data[6] * 64) + data[5]
        month = data[4]
        date = data[3]
        hours = data[2] & 0x3F
        minutes = data[1]
        seconds = data[0] & 0x7F
        try:
            return datetime(century * 100 + year, month, date, hours, minutes, seconds)
        except ValueError as e:
            raise IOError(f"Invalid RTC data: {e}")


    def write_datetime(self, dt):
        """Write a datetime object back to the RTC."""
        try:
            self.write_all(dt.second, dt.minute, dt.hour, dt.isoweekday(), dt.day, dt.month, dt.year % 100)
        except ValueError as e:
            raise IOError(f"Invalid datetime value: {e}")


    def write_now(self):
        """Write the current system time to the RTC."""
        now = datetime.now()
        self.write_datetime(now)


    def read_now(self):
        """Read the current time from the RTC."""
        return self.read_datetime()


def main():
    """Main demonstration loop."""
    with DS1338() as rtc:
        try:
            rtc.write_now()
            now = rtc.read_now()
            print("RTC time:", now.strftime("%Y-%m-%d %H:%M:%S"))
        except IOError as e:
            print(f"Error: {e}")


if __name__ == "__main__":
    main()

