        """Read all RTC registers."""
        try:
            data = self.bus.read_i2c_block_data(DS1338_ADDRESS, 0x00, 7)
        except Exception as e:
            raise IOError(f"Failed to read DS1338 registers: {e}")
        return data


    def write_all(self, seconds, minutes, hours, day, date, month, year):
        """Write all RTC registers."""
        data = [self._int_to_bcd(seconds), self._int_to_bcd(minutes), self._int_to_bcd(hours), day,
                self._int_to_bcd(date), self._int_to_bcd(month), self._int_to_bcd(year)]
        try:
            self.bus.write_i2c_block_data(DS1338_ADDRESS, 0x00, data)
        except Exception as e:
            raise IOError(f"Failed to write DS1338 registers: {e}")


