# Serial port configuration for the radiation sensor
SERIAL_PORT = '/dev/ttyUSB0'
BAUD_RATE = 9600
TIMEOUT = 1
READ_INTERVAL = 1  # seconds between readings

# GPIO pin for the alert LED
ALERT_LED_PIN = 18

def configure_serial(port, baudrate, timeout):
    """Open and configure the serial port."""
    try:
        ser = serial.Serial(port, baudrate, timeout=timeout)
        return ser
    except serial.SerialException as e:
        print(f"Error opening serial port: {e}")
        return None

def configure_gpio(pin):
    """Configure the GPIO pin for the alert LED."""
    GPIO.setmode(GPIO.BCM)
    GPIO.setup(pin, GPIO.OUT)

def read_radiation_level(serial_port):
    """Read a radiation level from the serial port."""
    try:
        line = serial_port.readline().decode('ascii', errors='replace').strip()
        if line:
            return float(line)
        return None
    except ValueError:
        print("Invalid data received from sensor")
        return None

def alert_led(pin, radiation_level, threshold):
    """Set the alert LED based on the radiation level."""
    if radiation_level > threshold:
        GPIO.output(pin, GPIO.HIGH)
    else:
        GPIO.output(pin, GPIO.LOW)

def main():
    """Main function to read radiation and control the LED."""
    serial_connection = configure_serial(SERIAL_PORT, BAUD_RATE, TIMEOUT)
    if serial_connection is None:
        exit(1)

    configure_gpio(ALERT_LED_PIN)

    try:
        while True:
            radiation_value = read_radiation_level(serial_connection)
            if radiation_value is not None:
                print(f"Radiation level: {radiation_value:.2f} µSv/h")
                alert_led(ALERT_LED_PIN, radiation_value, 50.0)
            time.sleep(READ_INTERVAL)
    except KeyboardInterrupt:
        print("Shutting down...")
    finally:
        serial_connection.close()
        GPIO.cleanup()

if __name__ == "__main__":
    main()

