# radiation monitoring station for Raspberry Pi using a UART sensor
# Reads radiation levels from a serial port and triggers an alarm on a GPIO pin
import serial
import time
import RPi.GPIO as GPIO

# Serial port configuration for the radiation sensor
SERIAL_PORT = '/dev/ttyUSB0'
BAUD_RATE = 9600
TIMEOUT = 1

# GPIO pin driving the alarm indicator
ALARM_GPIO_PIN = 18

# Radiation threshold for the alarm
RADIATION_THRESHOLD = 50.0


def open_serial_port(port, baud, timeout):
    """Open and return a serial port with the given settings."""
    try:
        return serial.Serial(port, baud, timeout=timeout)
    except serial.SerialException as error:
        print("Serial port error:", error)
        return None


def read_radiation_level(serial_port):
    """Read one line from the serial port and return the radiation level."""
    try:
        line = serial_port.readline().decode('ascii', errors='replace').strip()
        if line:
            return float(line)
        return None
    except ValueError:
        print("Invalid data received from sensor")
        return None
    except Exception as error:
        print("Read error:", error)
        return None


def set_alarm_state(pin, level, threshold):
    """Set the GPIO alarm pin HIGH when the radiation exceeds the threshold."""
    if level is not None:
        alarm_active = level > threshold
        GPIO.output(pin, GPIO.HIGH if alarm_active else GPIO.LOW)
        print("Alarm", "ON" if alarm_active else "OFF")


def main():
    """Main entry point: open the serial port, configure GPIO, and monitor radiation."""
    GPIO.setmode(GPIO.BCM)
    GPIO.setup(ALARM_GPIO_PIN, GPIO.OUT, initial=GPIO.LOW)
    serial_port = open_serial_port(SERIAL_PORT, BAUD_RATE, TIMEOUT)
    if serial_port is None:
        GPIO.cleanup()
        return

    try:
        while True:
            radiation_level = read_radiation_level(serial_port)
            if radiation_level is not None:
                print("Radiation level:", round(radiation_level, 2), "µSv/h")
                set_alarm_state(ALARM_GPIO_PIN, radiation_level, RADIATION_THRESHOLD)
            time.sleep(1)
    except KeyboardInterrupt:
        print("Stopping radiation monitor")
    finally:
        serial_port.close()
        GPIO.cleanup()


if __name__ == "__main__":
    main()

