# Reads water flow from a UART sensor and triggers an alarm on a GPIO pin.
# Designed for Raspberry Pi 3 Model B+ in a home automation context.

import serial
import time
import RPi.GPIO as GPIO

# Configuration
SERIAL_PORT = '/dev/ttyUSB0'
BAUD_RATE = 9600
FLOW_ALARM_PIN = 17
FLOW_THRESHOLD = 10.0  # L/min
READ_TIMEOUT = 1  # seconds

# Setup GPIO
GPIO.setmode(GPIO.BCM)
GPIO.setup(FLOW_ALARM_PIN, GPIO.OUT)

def configure_serial():
    """Configures the serial port for water flow sensor communication."""
    try:
        ser = serial.Serial(SERIAL_PORT, BAUD_RATE, timeout=READ_TIMEOUT)
        return ser
    except serial.SerialException as e:
        print(f"Error opening serial port: {e}")
        return None

def read_flow_rate(serial_port):
    """Reads the water flow rate from the serial port."""
    try:
        line = serial_port.readline().decode('ascii', errors='replace').strip()
        if line:
            return float(line)
        return None
    except ValueError:
        print("Invalid data received from sensor.")
        return None
    except serial.SerialException as e:
        print(f"Serial read error: {e}")
        return None

def set_alarm_state(alarm_pin, flow_rate, threshold):
    """Sets the GPIO alarm state based on the flow rate."""
    if flow_rate > threshold:
        GPIO.output(alarm_pin, GPIO.HIGH)  # Activate alarm
    else:
        GPIO.output(alarm_pin, GPIO.LOW)  # Deactivate alarm

def main():
    """Main function to read flow and control the alarm."""
    serial_connection = configure_serial()
    if serial_connection is None:
        return

    try:
        while True:
            flow = read_flow_rate(serial_connection)
            if flow is not None:
                print(f"Flow Rate: {flow:.2f} L/min")
                set_alarm_state(FLOW_ALARM_PIN, flow, FLOW_THRESHOLD)
            time.sleep(1)
    except KeyboardInterrupt:
        print("Program terminated by user.")
    finally:
        serial_connection.close()
        GPIO.cleanup()
        print("Resources cleaned up.")

if __name__ == "__main__":
    main()

