import time
import logging
import sys
from typing import Optional, Tuple

try:
    from machine import UART, Pin
except ImportError:
    print("machine module not found, using dummy UART")
    class UART:
        def __init__(self, id: int, baudrate: int, tx: Pin, rx: Pin, timeout: float = 0.0):
            pass

        def write(self, data: bytes):
            pass

        def read(self) -> bytes:
            pass

        @property
        def id(self) -> int:
            return 0

        @property
        def tx(self) -> Pin:
            return None

        @property
        def rx(self) -> Pin:
            return None

        @property
        def timeout(self) -> float:
            return 0.0

class ESP8266:
    """Driver for ESP8266 Wi-Fi module using AT commands over UART."""

    def __init__(self, uart_id: int = 0, baudrate: int = 115200, tx_pin: int = 14, rx_pin: int = 15) -> None:
        """Initializes the ESP8266 driver.

        Args:
            uart_id: The UART ID to use (default: 0).
            baudrate: The baud rate to use (default: 115200).
            tx_pin: The TX pin number (default: 14).
            rx_pin: The RX pin number (default: 15).
        """
        self._uart = UART(uart_id, baudrate=baudrate, tx=Pin(tx_pin), rx=Pin(rx_pin), txbuf=1024, rxbuf=2048,
                         timeout=5)  # Added timeout for better reliability
        self._logger = logging.getLogger(__name__)

    def _send_command(self, command: str, delay: float = 1) -> str:
        """Sends an AT command to the ESP8266 and returns the response.

        Args:
            command: The AT command to send.
            delay: The delay in seconds after sending the command.

        Returns:
            The response from the ESP8266, or None on timeout or error.

        Raises:
            Exception: If there's an unexpected error during communication.
        """
        self._logger.debug(f"Sending command: {command}")
        try:
            self._uart.write(command.encode())
            time.sleep(delay)
            response = self._read_response()
            if response:
                self._logger.debug(f"Received response: {response}")
                return response
            else:
                self._logger.warning("No response received within timeout.")
                return None
        except Exception as e:
            self._logger.exception(f"Error sending command: {e}")
            raise

    def _read_response(self) -> Optional[str]:
        """Reads the response from the ESP8266, handling timeouts.

        Returns:
            The response as a string, or None if an error occurred.
        """
        time.sleep(5)  # Increased timeout for more reliable reads
        response = b""
        while self._uart.any():
            response += self._uart.read(self._uart.any())
        if response:
            return response.decode()
        return None

    def test_connection(self) -> bool:
        """Tests the connection to the ESP8266.

        Returns:
            True if the connection is successful, False otherwise.
        """
        response = self._send_command("AT\r\n")
        return response and "OK" in response

    def restart(self) -> None:
        """Restarts the ESP8266.

        Raises:
            Exception: If the restart fails.
        """
        if not self.test_connection():
            raise Exception("ESP8266 not connected.")
        self._send_command("AT+RST\r\n", delay=2)  # Longer delay for restart
        time.sleep(5)  # Wait for restart
        if not self.test_connection():
            raise Exception("ESP8266 did not restart successfully.")

    def connect_wifi(self, ssid: str, password: str) -> bool:
        """Connects to a Wi-Fi network.

        Args:
            ssid: The SSID of the network.
            password: The password of the network.

        Returns:
            True if the connection is successful, False otherwise.
        """
        if not self.test_connection():
            raise Exception("ESP8266 not connected.")

        command = f'AT+CWJAP_CUR="{ssid}","{password}"\r\n'
        response = self._send_command(command, delay=5)
        if "WIFI GOT IP" in response:
            self._logger.info(f"Connected to {ssid}, got IP: {response}")
            return True
        else:
            self._logger.error(f"Failed to connect to {ssid}: {response}")
            return False

    def get_ip(self) -> Optional[str]:
        """Retrieves the IP address of the ESP8266.

        Returns:
            The IP address as a string, or None if an error occurs.
        """
        response = self._send_command("AT+CIFSR\r\n")
        if response and "STAIP," in response:
            try:
                ip = response.split("STAIP,")[1].split(",")[0]
                return ip.strip('"')  # Remove any quotes around the IP
            except IndexError:
                self._logger.warning("Invalid IP format in response.")
                return None
        return None


def main() -> None:
    """Main function to demonstrate ESP8266 usage."""
    logging.basicConfig(level=logging.INFO, format="%(asctime)s - %(levelname)s - %(message)s")
    logger = logging.getLogger(__name__)
    try:
        esp = ESP8266(uart_id=0, tx_pin=14, rx_pin=15)
        if esp.test_connection():
            ip = esp.get_ip()
            if ip:
                logger.info(f"IP address: {ip}")
            else:
                logger.error("Failed to retrieve IP address.")
        else:
            logger.error("ESP8266 not connected. Check wiring and power.")
    except Exception as e:
        logger.exception(f"An unexpected error occurred: {e}")
    finally:
        # No specific cleanup needed for UART in this simple example, but including for potential future expansion
        logger.info("ESP8266 communication ended.")


if __name__ == "__main__":
    main()

