# pulse_oximeter_uart_procedural.py
# Reads pulse oximeter data from a UART port on a Raspberry Pi
# This version uses a functional approach with error handling and resource management

import serial
import time

# Serial port configuration for the pulse oximeter
SERIAL_PORT = '/dev/ttyUSB0'
BAUD_RATE = 9600
BITS_PER_BYTE = 8
PARITY = serial.PARITY_NONE
STOP_BITS = 1
TIMEOUT = 1

def configure_serial_port(port, baudrate, bits, parity, stop, timeout):
    """Configures and returns a serial port object."""
    try:
        ser = serial.Serial(port, baudrate, bytesize=bits, parity=parity, stopbits=stop, timeout=timeout)
        return ser
    except serial.SerialException as e:
        print(f"Error opening serial port: {e}")
        return None

def read_pulse_oximeter_data(serial_port):
    """Reads a line of data from the serial port and returns it."""
    try:
        line = serial_port.readline().decode('ascii', errors='replace').strip()
        return line
    except serial.SerialException as e:
        print(f"Error reading from serial port: {e}")
        return None

def process_pulse_oximeter_data(line):
    """Processes the received data, splitting it into heart rate and SpO2."""
    if not line:
        return None, None
    try:
        heart_rate, spo2 = line.split(',')
        return heart_rate, spo2
    except ValueError as e:
        print(f"Error parsing data: {e}.  Received: {line}")
        return None, None

def display_pulse_oximeter_data(heart_rate, spo2):
    """Prints the heart rate and SpO2 to the console."""
    if heart_rate is not None and spo2 is not None:
        print(f"Heart Rate: {heart_rate} bpm, SpO2: {spo2} %")

def main():
    """Main function to read and display pulse oximeter data."""
    serial_connection = configure_serial_port(SERIAL_PORT, BAUD_RATE, BITS_PER_BYTE, PARITY, STOP_BITS, TIMEOUT)

    if serial_connection is None:
        print("Failed to configure serial port. Exiting.")
        return

