ITEM_ID_COUNT = 2  # Number of unique item IDs to generate
IN_MEMORY_DATA = [{"id": 1, "name": "Item 1", "done": False}, {"id": 2, "name": "Item 2", "done": False}]

# Global variable for serial port
serial_port = None


def create_serial_connection(port: str, baudrate: int) -> Optional[serial.Serial]:
    """Creates a serial connection.

    Args:
