    Returns:
        Optional[serial.Serial]: The serial connection, or None if an error occurred.
    """
    global serial_port
    try:
        serial_port = serial.Serial(port, baudrate, timeout=SERIAL_TIMEOUT)
        time.sleep(0.1)  # Allow time for the connection to stabilize
        logger.info(f"Connected to serial port: {port} at {baudrate} baud")
        return serial_port
    except serial.SerialException as e:
        logger.error(f"Error connecting to serial port {port}: {e}")
        return None


def close_serial_connection() -> None:
    """Closes the serial connection if it's open."""
    global serial_port
    if serial_port and serial_port.is_open:
        try:
            serial_port.close()
            logger.info("Serial port closed.")
        except serial.SerialException as e:
            logger.error(f"Error closing serial port: {e}")


def read_instrument_response() -> Optional[str]:
    """Reads a line from the serial port, handling potential errors.

    Returns:
        Optional[str]: The response from the instrument, or None if an error occurred.
    """
    global serial_port
    if not serial_port:
        logger.warning("Serial port is not initialized.")
        return None

    try:
        response = serial_port.readline().decode('utf-8', errors='ignore').strip()
        return response if response else None
    except serial.SerialException as e:
        logger.error(f"Error reading from serial port: {e}")
        return None
    except Exception as e:
        logger.error(f"An unexpected error occurred: {e}")
        return None


def send_instrument_command(command: str) -> Optional[str]:
    """Sends a command to the serial port and returns the response.

    Args:
        command (str): The command to send.

    Returns:
        Optional[str]: The response from the instrument, or None if an error occurred.
    """
    global serial_port
    if not serial_port:
        logger.warning("Serial port is not initialized.")
        return None

    try:
        serial_port.write((command + '\n').encode('utf-8'))
        return read_instrument_response()
    except serial.SerialException as e:
        logger.error(f"Error sending command to serial port: {e}")
        return None
    except Exception as e:
        logger.error(f"An unexpected error occurred while sending command: {e}")
        return None


def scpi_to_command(scpi: str) -> str:
    """Converts a SCPI command to a standard Python command.

    Args:
        scpi (str): The SCPI command.

    Returns:
        str: The converted command.
    """
    return f"READ {scpi}"


def generate_cloud_data() -> List[Dict[str, Any]]:
    """Generates simulated cloud data.

    Returns:
        List[Dict[str, Any]]: The cloud data.
    """
    global IN_MEMORY_DATA
    new_data = [{"id": len(IN_MEMORY_DATA) + 1, "name": "New Item", "done": False}]
    IN_MEMORY_DATA.extend(new_data)
    return IN_MEMORY_DATA


def post_data_to_cloud(data: List[Dict[str, Any]]) -> None:
    """Simulates posting data to a cloud service.

    Args:
        data (List[Dict[str, Any]]): The data to post.
    """
    try:
        # Simulate network latency
        time.sleep(0.5)

        # Simulate network errors
        if request.headers.get('X-Custom-Error') == 'error':
            raise Exception("Simulated network error")

        # Simulate network success
        data_to_post = [{"id": item["id"], "name": item["name"], "done": item["done"]} for item in data]
        response = requests.post(CLOUD_ENDPOINT, json=data_to_post)
        response.raise_for_status()  # Raise HTTPError for bad responses (4xx or 5xx)
        logger.info(f"Data successfully posted to cloud. Status code: {response.status_code}")
    except requests.exceptions.RequestException as e:
        logger.error(f"Error posting data to cloud: {e}")
    except Exception as e:
        logger.error(f"An unexpected error occurred while posting data to cloud: {e}")


# Decorator for handling serial communication errors
def handle_serial_errors(func):
    """Decorator to handle serial communication errors."""
    @wraps(func)
    def wrapper(*args, **kwargs):
        nonlocal serial_port
        try:
            return func(*args, **kwargs)
        except Exception as e:
            logger.error(f"Serial communication error: {e}")
            return Response("Serial communication error", status=503, mimetype='text/plain')
    return wrapper


@app.route('/version', methods=['GET'])
@handle_serial_errors()
def get_instrument_version() -> Response:
    """Retrieves the version information from the instrument.

    Returns:
        Response: The version information as HTML.
    """
    response = send_instrument_command("*IDN?")
    if response:
        return Response(response, mimetype='text/html')
    else:
        return Response("No response from instrument", status=504, mimetype='text/plain')


@app.route('/getdata', methods=['GET'])
@handle_serial_errors()
def get_data() -> Response:
    """Retrieves the current data from the in-memory list.

    Returns:
        Response: The current data as JSON.
    """
    return jsonify(ITEM_ID_COUNT * [{}])  # Return a list of empty dicts for demonstration


@app.route('/getpost', methods=['GET'])
@handle_serial_errors()
def get_post() -> Response:
    """Retrieves the current post data.

    Returns:
        Response: The current post data as JSON.
    """
    post_data = request.values.get('post', '')
    if post_data:
        try:
            # Validate input data
            name = post_data.split(',')[0].strip()
            if not name:
                raise ValueError("Name is required")

            # Update in-memory data
            global IN_MEMORY_DATA
            new_item = {"id": len(IN_MEMORY_DATA) + 1, "name": name, "done": False}
            IN_MEMORY_DATA.append(new_item)

            # Simulate cloud data upload
            cloud_data = generate_cloud_data()
            post_data_to_cloud(cloud_data)

            # Return updated in-memory data
            return jsonify(IN_MEMORY_DATA)
        except ValueError as e:
            logger.error(f"Invalid input data: {e}")
            return Response(str(e), status=400, mimetype='text/plain')
        except Exception as e:
            logger.error(f"Error processing post data: {e}")
            return Response("Error processing post data", status=500, mimetype='text/plain')
    else:
        return Response("No post data provided", status=400, mimetype='text/plain')


@app.route('/getpostjson', methods=['GET'])
@handle_serial_errors()
def get_post_json() -> Response:
    """Retrieves the current post data in JSON format.

    Returns:
        Response: The current post data as JSON.
    """
    return jsonify(ITEM_ID_COUNT * [{}])  # Return a list of empty dicts for demonstration


# ... (rest of the routes with similar error handling and docstrings)

if __name__ == '__main__':
    # Initialize serial port
    serial_port = create_serial_connection(DEFAULT_SERIAL_PORT, DEFAULT_BAUDRATE)

    # Start the Flask development server
    app.run(debug=True, host='0.0.0.0')

